class VanillaOption(ContingentClaim):
    """Standard European/American call and put options"""

    def __init__(self, option_type: OptionType, underlying_type: UnderlyingType, expiry_date: datetime, strike_price: float, exercise_style: ExerciseStyle=ExerciseStyle.EUROPEAN, notional: float=1.0):
        super().__init__(option_type, underlying_type, expiry_date, strike_price, exercise_style, notional)

    def calculate_payoff(self, spot_price: float) -> float:
        """Calculate option payoff at expiration"""
        if self.option_type == OptionType.CALL:
            return max(0, spot_price - self.strike_price) * self.notional
        else:
            return max(0, self.strike_price - spot_price) * self.notional

    def fair_value(self, market_data: MarketData) -> PricingResult:
        """Calculate fair value using appropriate model"""
        if self.exercise_style == ExerciseStyle.EUROPEAN:
            return self._black_scholes_price(market_data)
        else:
            return self._binomial_price(market_data, steps=100)

    def _black_scholes_price(self, market_data: MarketData) -> PricingResult:
        """Black-Scholes-Merton pricing for European options"""
        S = market_data.spot_price
        K = self.strike_price
        T = self.time_to_expiry()
        r = market_data.risk_free_rate
        q = market_data.dividend_yield
        sigma = market_data.volatility
        if T <= 0:
            return PricingResult(fair_value=self.calculate_payoff(S))
        d1 = (np.log(S / K) + (r - q + 0.5 * sigma ** 2) * T) / (sigma * np.sqrt(T))
        d2 = d1 - sigma * np.sqrt(T)
        if self.option_type == OptionType.CALL:
            price = S * np.exp(-q * T) * norm.cdf(d1) - K * np.exp(-r * T) * norm.cdf(d2)
        else:
            price = K * np.exp(-r * T) * norm.cdf(-d2) - S * np.exp(-q * T) * norm.cdf(-d1)
        price *= self.notional
        intrinsic = self.intrinsic_value(S)
        return PricingResult(fair_value=price, intrinsic_value=intrinsic, time_value=price - intrinsic, calculation_details={'model': 'Black-Scholes-Merton', 'd1': d1, 'd2': d2, 'N_d1': norm.cdf(d1) if self.option_type == OptionType.CALL else norm.cdf(-d1), 'N_d2': norm.cdf(d2) if self.option_type == OptionType.CALL else norm.cdf(-d2)})

    def _binomial_price(self, market_data: MarketData, steps: int=50) -> PricingResult:
        """Binomial tree pricing for American options"""
        engine = BinomialPricingEngine(steps)
        return engine.price(self, market_data)

def __init__(self, option_type: OptionType, underlying_type: UnderlyingType, expiry_date: datetime, strike_price: float, exercise_style: ExerciseStyle=ExerciseStyle.EUROPEAN, notional: float=1.0):
    super().__init__(option_type, underlying_type, expiry_date, strike_price, exercise_style, notional)

class EquityForward(ForwardCommitment):
    """Equity forward contract implementation"""

    def __init__(self, underlying_symbol: str, expiry_date: datetime, contract_price: float, notional: float=1.0, day_count: DayCountConvention=DayCountConvention.ACT_365):
        super().__init__(DerivativeType.FORWARD, UnderlyingType.EQUITY, expiry_date, contract_price, notional, day_count)
        self.underlying_symbol = underlying_symbol

    def calculate_payoff(self, spot_price: float) -> float:
        """Calculate payoff at expiration"""
        return self.notional * (spot_price - self.contract_price)

    def fair_value(self, market_data: MarketData) -> PricingResult:
        """Calculate fair value using carry arbitrage model"""
        time_to_expiry = self.time_to_expiry()
        carry_rate = market_data.risk_free_rate - market_data.dividend_yield
        theoretical_forward_price = market_data.spot_price * np.exp(carry_rate * time_to_expiry)
        discount_factor = np.exp(-market_data.risk_free_rate * time_to_expiry)
        fair_value = (self.contract_price - theoretical_forward_price) * discount_factor * self.notional
        return PricingResult(fair_value=fair_value, calculation_details={'theoretical_forward_price': theoretical_forward_price, 'market_forward_price': self.contract_price, 'carry_rate': carry_rate, 'discount_factor': discount_factor, 'time_to_expiry': time_to_expiry})

def __init__(self, underlying_symbol: str, expiry_date: datetime, contract_price: float, notional: float=1.0, day_count: DayCountConvention=DayCountConvention.ACT_365):
    super().__init__(DerivativeType.FORWARD, UnderlyingType.EQUITY, expiry_date, contract_price, notional, day_count)
    self.underlying_symbol = underlying_symbol

class InterestRateForward(ForwardCommitment):
    """Interest rate forward contract (FRA - Forward Rate Agreement)"""

    def __init__(self, start_date: datetime, end_date: datetime, contract_rate: float, notional: float=1000000, day_count: DayCountConvention=DayCountConvention.ACT_360, currency: str='USD'):
        super().__init__(DerivativeType.FORWARD, UnderlyingType.INTEREST_RATE, end_date, contract_rate, notional, day_count)
        self.start_date = start_date
        self.currency = currency
        if start_date >= end_date:
            raise ValidationError('Start date must be before end date')

    def calculate_payoff(self, market_rate: float) -> float:
        """Calculate FRA payoff at settlement"""
        period_length = calculate_time_fraction(self.start_date, self.expiry_date, self.day_count)
        rate_diff = market_rate - self.contract_price
        payoff = rate_diff * period_length * self.notional / (1 + market_rate * period_length)
        return payoff

    def fair_value(self, market_data: MarketData) -> PricingResult:
        """Calculate FRA fair value using forward rates"""
        data_manager = MarketDataManager()
        yield_curve = data_manager.primary_provider.get_yield_curve(self.currency)
        t1 = calculate_time_fraction(datetime.now(), self.start_date, self.day_count)
        t2 = calculate_time_fraction(datetime.now(), self.expiry_date, self.day_count)
        r1 = yield_curve.interpolate_rate(t1)
        r2 = yield_curve.interpolate_rate(t2)
        if self.day_count == DayCountConvention.ACT_360:
            forward_rate = ((1 + r2 * t2) / (1 + r1 * t1) - 1) / (t2 - t1)
        else:
            forward_rate = (r2 * t2 - r1 * t1) / (t2 - t1)
        period_length = calculate_time_fraction(self.start_date, self.expiry_date, self.day_count)
        rate_diff = forward_rate - self.contract_price
        discount_factor = np.exp(-r1 * t1)
        fair_value = rate_diff * period_length * self.notional * discount_factor / (1 + forward_rate * period_length)
        return PricingResult(fair_value=fair_value, calculation_details={'forward_rate': forward_rate, 'contract_rate': self.contract_price, 'period_length': period_length, 't1': t1, 't2': t2, 'r1': r1, 'r2': r2, 'discount_factor': discount_factor})

def __init__(self, start_date: datetime, end_date: datetime, contract_rate: float, notional: float=1000000, day_count: DayCountConvention=DayCountConvention.ACT_360, currency: str='USD'):
    super().__init__(DerivativeType.FORWARD, UnderlyingType.INTEREST_RATE, end_date, contract_rate, notional, day_count)
    self.start_date = start_date
    self.currency = currency
    if start_date >= end_date:
        raise ValidationError('Start date must be before end date')

class FixedIncomeForward(ForwardCommitment):
    """Fixed income forward contract"""

    def __init__(self, bond_details: Dict, expiry_date: datetime, contract_price: float, notional: float=100, day_count: DayCountConvention=DayCountConvention.ACT_365):
        super().__init__(DerivativeType.FORWARD, UnderlyingType.BOND, expiry_date, contract_price, notional, day_count)
        self.bond_details = bond_details
        self.coupon_rate = bond_details.get('coupon_rate', 0.0)
        self.face_value = bond_details.get('face_value', 100)
        self.maturity_date = bond_details.get('maturity_date')

    def calculate_payoff(self, bond_price: float) -> float:
        """Calculate payoff at expiration"""
        return self.notional * (bond_price - self.contract_price)

    def fair_value(self, market_data: MarketData) -> PricingResult:
        """Calculate fair value with accrued interest consideration"""
        time_to_expiry = self.time_to_expiry()
        coupon_pv = self._calculate_coupon_pv(market_data.risk_free_rate, time_to_expiry)
        adjusted_spot = market_data.spot_price - coupon_pv
        theoretical_forward_price = adjusted_spot * np.exp(market_data.risk_free_rate * time_to_expiry)
        discount_factor = np.exp(-market_data.risk_free_rate * time_to_expiry)
        fair_value = (self.contract_price - theoretical_forward_price) * discount_factor * self.notional
        return PricingResult(fair_value=fair_value, calculation_details={'theoretical_forward_price': theoretical_forward_price, 'coupon_pv': coupon_pv, 'adjusted_spot_price': adjusted_spot, 'time_to_expiry': time_to_expiry})

    def _calculate_coupon_pv(self, risk_free_rate: float, time_to_expiry: float) -> float:
        """Calculate present value of coupons paid during forward period"""
        annual_coupon = self.coupon_rate * self.face_value
        semi_annual_coupon = annual_coupon / 2
        coupon_pv = 0.0
        coupon_frequency = 0.5
        for i in range(1, int(time_to_expiry / coupon_frequency) + 1):
            coupon_time = i * coupon_frequency
            if coupon_time <= time_to_expiry:
                coupon_pv += semi_annual_coupon * np.exp(-risk_free_rate * coupon_time)
        return coupon_pv

def __init__(self, bond_details: Dict, expiry_date: datetime, contract_price: float, notional: float=100, day_count: DayCountConvention=DayCountConvention.ACT_365):
    super().__init__(DerivativeType.FORWARD, UnderlyingType.BOND, expiry_date, contract_price, notional, day_count)
    self.bond_details = bond_details
    self.coupon_rate = bond_details.get('coupon_rate', 0.0)
    self.face_value = bond_details.get('face_value', 100)
    self.maturity_date = bond_details.get('maturity_date')

class ManualDataProvider(MarketDataProvider):
    """Manual data input provider for custom scenarios"""

    def __init__(self):
        super().__init__(DataProvider.MANUAL)
        self.data_cache = {}
        self.connection_status = True

    def connect(self, **kwargs) -> bool:
        self.connection_status = True
        return True

    def disconnect(self) -> bool:
        self.connection_status = False
        return True

    def set_spot_price(self, symbol: str, price: float):
        """Manually set spot price"""
        ModelValidator.validate_positive(price, f'spot price for {symbol}')
        self.data_cache[f'spot_{symbol}'] = price
        self.last_update = datetime.now()

    def set_risk_free_rate(self, rate: float, currency: str='USD', maturity: float=0.25):
        """Manually set risk-free rate"""
        ModelValidator.validate_rate(rate, f'risk-free rate for {currency}')
        self.data_cache[f'rf_{currency}_{maturity}'] = rate
        self.last_update = datetime.now()

    def set_dividend_yield(self, symbol: str, yield_rate: float):
        """Manually set dividend yield"""
        ModelValidator.validate_non_negative(yield_rate, f'dividend yield for {symbol}')
        self.data_cache[f'div_{symbol}'] = yield_rate
        self.last_update = datetime.now()

    def set_volatility(self, symbol: str, volatility: float, maturity: float=None, strike: float=None):
        """Manually set volatility"""
        ModelValidator.validate_volatility(volatility)
        key = f'vol_{symbol}'
        if maturity is not None:
            key += f'_{maturity}'
        if strike is not None:
            key += f'_{strike}'
        self.data_cache[key] = volatility
        self.last_update = datetime.now()

    def get_spot_price(self, symbol: str) -> float:
        key = f'spot_{symbol}'
        if key not in self.data_cache:
            raise ValueError(f'No spot price data for symbol: {symbol}')
        return self.data_cache[key]

    def get_risk_free_rate(self, currency: str='USD', maturity: float=0.25) -> float:
        key = f'rf_{currency}_{maturity}'
        if key not in self.data_cache:
            default_key = f'rf_{currency}_0.25'
            if default_key in self.data_cache:
                return self.data_cache[default_key]
            return 0.02
        return self.data_cache[key]

    def get_dividend_yield(self, symbol: str) -> float:
        key = f'div_{symbol}'
        return self.data_cache.get(key, 0.0)

    def get_volatility(self, symbol: str, maturity: float, strike: float=None) -> float:
        key = f'vol_{symbol}_{maturity}'
        if strike is not None:
            key += f'_{strike}'
        if key in self.data_cache:
            return self.data_cache[key]
        key_no_strike = f'vol_{symbol}_{maturity}'
        if key_no_strike in self.data_cache:
            return self.data_cache[key_no_strike]
        generic_key = f'vol_{symbol}'
        if generic_key in self.data_cache:
            return self.data_cache[generic_key]
        return 0.2

    def get_yield_curve(self, currency: str, curve_type: str='government') -> CurveData:
        """Get yield curve (simplified for manual input)"""
        curve = CurveData(curve_date=datetime.now(), curve_type=curve_type, currency=currency, day_count=DayCountConvention.ACT_365)
        default_rates = [(0.25, 0.02), (0.5, 0.022), (1.0, 0.025), (2.0, 0.028), (5.0, 0.032), (10.0, 0.035), (30.0, 0.038)]
        for maturity, rate in default_rates:
            rf_rate = self.get_risk_free_rate(currency, maturity)
            curve.add_point(maturity, rf_rate)
        return curve

def __init__(self):
    super().__init__(DataProvider.MANUAL)
    self.data_cache = {}
    self.connection_status = True

